# Authoring helper for demo seed v1: writes ledger.json, the machine form of the parameter ledger.
# Every stated value is typed here by hand; nothing is computed from a formula in this file except
# min_count (by the rule in _meta). Two frozen snapshots are read: checks/accepted_rows.json (rows another part
# proposed) and checks/new_facts.json (the new facts of the story calls and conversations). checks/check_ledger.py evaluates the formulas independently.
# Not product code. Run: python3 checks/build_ledger.py
import json, math, os, re

OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "ledger.json")
ROWS, SEEN = [], set()


def R(key, v=None, unit="", cls="designed", mark="fixed", stories=(), check="", en=None, ru=None, **x):
    assert key not in SEEN, key
    SEEN.add(key)
    row = {"key": key}
    if en is not None or ru is not None:
        row["en"], row["ru"] = en, ru
    else:
        row["value"] = v
    row.update(unit=unit, **{"class": cls}, mark=mark)
    if cls == "derived":
        assert "formula" in x, key
    if cls in ("measured", "measured-unverified"):
        assert "source" in x, key
    if cls == "designed":
        assert "reasoning" in x, key
    if mark == "rate":
        assert "tolerance" in x and "n" in x, key
        if "min_count" not in x:
            vals = [a for a in ([v] if en is None and ru is None else [en, ru]) if isinstance(a, (int, float))]
            p = min(min(a, 100 - a) for a in vals) / 100 if vals else 0
            x["min_count"] = math.ceil(max(0.5 / (x["tolerance"] / 100), 5 / p if p > 0 else 0))
    row.update(x)
    row["stories"] = list(stories)
    row["check"] = check
    ROWS.append(row)


D, M, MU, X = "derived", "measured", "measured-unverified", "designed"
SITES = ("main", "east", "west")

