    R(f"acct.{a}.visits", vis, "orders in each 30-day block: the first value is every block before T-150 days, then the five blocks to T", cls=X, reasoning="design S1; review 24: a row per account over time; planted, the same in both sizes", mark="fixed", stories=["S1", "S16"], check="orders of the customer by 30-day block")
    R(f"acct.{a}.average_order", en=aen, ru=aru, unit="money per order before tax", cls=X, reasoning="A1's vans carry the bigger jobs, A2's weekly slot is mostly maintenance, A4's are small cars; A1 and A2 at account prices", mark="rate", tolerance=5.0, tolerance_unit="per cent of the value", min_count=40, n=f"{sum(vis[1:]) + vis[0] * 7}", stories=["S1", "S16"], check="orders of the customer, last 12 months")
    R(f"acct.{a}.state", state, cls=X, reasoning="design S1", stories=["S1"], check="-")
