# ------------------------------------------------------------------ the knowledge base (kb/): its tree, and every fact its pages introduced
# A kb.* row is a fact the knowledge base states and no other seed file held. It names the page that states it and the
# store that must carry it, so that the shop-system database, the roster, the call scripts, the team notes and the
# tenant settings can be built to match. Where a row and the data disagree on purpose, the reasoning says so and names
# the question that uses the gap. checks/check_kb.py fails when a page and a row differ.
def KB(key, unit, page, store, why, en=None, ru=None, v=None, stories=(), gap=None):
    kw = dict(unit=unit, cls=X, reasoning=why + (((" NOTE: " if gap.startswith(("none", "not a planted gap")) else " DELIBERATE GAP: ") + gap) if gap else ""), page=page, store=store, stories=stories, check="the text of " + (page if isinstance(page, str) else ", ".join(page)) + ", by checks/check_kb.py; carried by: " + store)
    if v is not None: R("kb." + key, v, **kw)
    else: R("kb." + key, en=en, ru=ru, **kw)
ERP, ROSTER, CALLS, NOTES, SETTINGS, ENGINE, NONE = "the shop-system database", "the roster", "the call scripts", "team notes", "tenant settings", "the knowledge engine", "no other store"

