# U() replaces fields of a row stated above (the key never changes); each R() below is a new row.
BY = {r["key"]: r for r in ROWS}


def U(key, **x):
    r = BY[key]
    if "v" in x:
        assert "value" in r, key
        r["value"] = x.pop("v")
    if "en" in x or "ru" in x:
        r.pop("value", None)
        r["en"], r["ru"] = x.pop("en", r.get("en")), x.pop("ru", r.get("ru"))
    if "cls" in x:
        r["class"] = x.pop("cls")
    r.update(x)


