# Russian amounts before tax: the list figure divided by tax.vat_divisor (bills of the last 12 months are all after 2025-01-01)
# The 12-month rows are at the prices in force on each order's day: the hour of price.hour.history, parts drifting before G (price.parts_drift_year)
NOMINAL = "at the nominal T; a build on another day differs by under 0.2 %"
R("price.year_blend.labour", en=0.9552, ru=0.9493, unit="what labour money at today's hour is multiplied by to give its mean over the 365 days before T, each day at the hour in force (price.hour.history); " + NOMINAL, cls=D,
  formula={"en": "(221 * [price.hour.history][0][1] + 144 * [price.hour.history][1][1]) / 365 / [price.hour.history][-1][1]", "ru": "(30 * [price.hour.history][1][1] + 191 * [price.hour.history][2][1] + 144 * [price.hour.history][3][1]) / 365 / [price.hour.history][-1][1]"},
  check="days of the 365 before T at each hour: en 221 at 125 and 144 at 135; ru 30 at 1,620, 191 at 1,760 and 144 at 1,900")
R("price.year_blend.parts", en=0.9959, ru=0.983, unit="what part, fee and sublet money at today's list is multiplied by to give its mean over the 365 days before T: today's price for the 175 days from G, today's price x (1 - price.parts_drift_year / 100) ^ (days before G / 365.25) for the 190 days before it; " + NOMINAL, cls=D,
  formula="(175 + sum((1 - [price.parts_drift_year] / 100) ** (d / 365.25) for d in range(1, 191))) / 365", check="order_part.price by month for one part: flat from G, drifting before it")
PT = "[volume.parts_per_order_list] / [tax.vat_divisor] / ((1 - 0.01) * (1 - [comeback.company] / 100))"  # parts per paying order at today's list, before tax
AT = "[volume.average_order_list] / [tax.vat_divisor] / (1 - [comeback.company] / 100)"  # a paying order at today's prices, before tax
R("price.year_blend.order", en=0.9737, ru=0.9715, unit="what a paying order's money at today's prices is multiplied by to give its mean over the 365 days before T: the labour and parts blends weighted by today's labour and parts per paying order; " + NOMINAL, cls=D,
  formula=f"(({AT} - {PT}) * [price.year_blend.labour] + {PT} * [price.year_blend.parts]) / ({AT})", check="sum(total before tax) / paying orders over the same at today's prices")
R("volume.parts_per_order_list", en=235, ru=7800, unit="money per order that is not labour, at list (ru: VAT inside)", cls=X, reasoning=BY["volume.parts_per_order"]["reasoning"], range={"en": [200, 280], "ru": [6500, 9000]}, check="catalogue check: parts and other per order within 2 % (mix.json ledger_targets)")
U("volume.parts_per_order", en=242.8, ru=7569.1, cls=D, formula=f"{PT} * [price.year_blend.parts]", unit="money per paying order that is not labour, before tax, last 12 months, at the prices in force on each order's day", check="sum of part, fee and sublet lines before tax / paying orders")
BY["volume.parts_per_order"].pop("reasoning", None); BY["volume.parts_per_order"].pop("range", None)
R("volume.average_order_list", en=521.9, ru=11980, unit="money per order at list, company, last 12 months (en before sales tax; ru as billed, VAT inside)", cls=D, formula="[volume.hours_per_order] * [price.hour.posted] * [price.effective_rate_list] + [volume.parts_per_order_list]", check="mix.json ledger_targets.average_order; the catalogue check")
U("volume.average_order", en=522.0, ru=11374.4, formula=f"{AT} * [price.year_blend.order]", unit="money per paying order before tax, company, last 12 months, at the prices in force on each order's day (ru: 11,943 as billed)")
for s, en, ru, paid_en, paid_ru, billed in (("main", 511.6, 11770, 510.4, 11159, 11717), ("east", 565.4, 12826, 562.3, 12122, 12728), ("west", 489.6, 11402, 495.4, 10912, 11457)):
    R(f"volume.average_order_list.{s}", en=en, ru=ru, unit="money per order at list (en before sales tax; ru as billed, VAT inside)", cls=D, formula=f"[volume.average_order_list] + [volume.value_per_sold_share] * ([sold.{s}] - [sold.company]) / 100", check="mix.json ledger_targets.average_order_by_shop")
    U(f"volume.average_order.{s}", en=paid_en, ru=paid_ru, formula=f"[volume.average_order_list.{s}] / [tax.vat_divisor] / (1 - [comeback.{s}] / 100) * [price.year_blend.order]", unit=f"money per paying order before tax, last 12 months, at the prices in force on each order's day (ru: {billed:,} as billed)")
R("volume.labour_per_order", en=279.2, ru=3805.3, unit="labour money net of discounts per paying order before tax, company, last 12 months, at the prices in force on each order's day", cls=D, formula="[volume.average_order] - [volume.parts_per_order]", check="sum(labour - discounts, before tax) / paying orders")
R("price.effective_rate_net", en=0.866, ru=0.9589, unit="labour money before tax per billed hour over the posted hour (ru: the posted hour holds VAT)", cls=D, formula="[price.effective_rate] / [tax.vat_divisor]", check="labour sales before tax / (sold hours x posted hour)")
# Paying orders. The catalogue is priced against the _list rows, which average over all orders with the free warranty and goodwill ones at nothing
# (mix.realisation); a shop measures its paying orders, and a discount comes off labour alone
R("price.effective_rate_list", en=0.85, ru=1.0, unit="labour money per billed hour over the posted hour that the catalogue is priced to: over all orders, the free warranty and goodwill ones at nothing", cls=M, source=BY["price.effective_rate"].pop("source"), check="mix.json ledger_targets.effective_labour_rate; the catalogue check")
U("price.effective_rate", en=0.866, ru=1.007, cls=D, formula="[volume.labour_per_order] / [price.year_blend.labour] * [tax.vat_divisor] / ([volume.hours_per_order] * [price.hour.posted])", unit="labour money net of discounts per billed hour over the posted hour in force on the order's day, paying orders, both as billed (the amount before tax: price.effective_rate_net)", check="(labour - discounts) / (sold hours x posted hour), paying orders")
U("price.hour.posted", unit="posted labour hour today (ru: VAT inside)")
U("volume.value_per_sold_share", unit="money per order at list for each 100 points of recommended work sold (ru: VAT inside)")
for s, en, ru in (("main", 2.297, 51.34), ("east", 1.540, 34.49), ("west", 1.091, 26.83)):
    U(f"volume.revenue_year.{s}", en=en, ru=ru, unit="million before tax, the last 12 months", formula=f"[volume.orders_per_month.{s}] * 12 * (1 - [comeback.{s}] / 100) * [volume.average_order.{s}] / 1e6")
U("volume.revenue_year.company", en=4.928, ru=112.66, unit="million before tax, the last 12 months", tolerance=5.0, tolerance_unit="per cent of the value", check="within 5 % (orders a month 3 % plus average order 2 %); RU inside the 5 % VAT band of 2026 (tax.ru_thresholds)")
R("volume.revenue_year_list.company", en=5.061, ru=121.76, unit="million a year at list, three shops (en before sales tax; ru as billed, VAT inside)", cls=D, formula="([volume.orders_per_month.main] * [volume.average_order_list.main] + [volume.orders_per_month.east] * [volume.average_order_list.east] + [volume.orders_per_month.west] * [volume.average_order_list.west]) * 12 / 1e6", mark="scales", check="sum of order totals as billed")
U("s2.f1.orders", tolerance=3.0, tolerance_unit="per cent of the value", check="orders by advisor: his visits, voids among them; within 3 % at full size")
# The last 30 days are a season of their own (ru: the autumn tyre window), so a share of "the last 30 days' orders" divides by that season's month
R("season.last_30_days", en=0.984, ru=1.451, unit="mean seasonal index of a day's orders over the 30 days before T, at the nominal T (a Tuesday build of that week differs by under 2 %)", cls=D, formula="season_last(30)", stories=["S1"], check="orders per day in the last 30 days over the yearly mean")
U("acct.six.orders_share_now", en=7.8, ru=5.04, formula=f"({VIS(5)}) / ([volume.orders_per_month.company] * [season.last_30_days]) * 100", unit="% of the last 30 days' orders, at the season of those days", check="full size only: the six's visits over all orders of the 30 days")
for k in ("acct.six.revenue_share_before", "acct.six.revenue_share_now", "acct.big_two_share"):  # before tax over before tax, a month at today's prices
    U(k, unit=BY[k]["unit"] + " (ru: the same share as billed, every order dividing by tax.vat_divisor; it is the share the catalogue's realisation factor counts)",
      formula=BY[k]["formula"].replace("[volume.revenue_year.company]", "[volume.revenue_year_list.company] / [tax.vat_divisor]"))
for a, net in (("A1", 12857.14), ("A2", 8761.9), ("A3", 9904.76), ("A4", 7142.86), ("A5", 12000.0), ("A6", 10380.95)):  # an account pays the table price, VAT inside (tax.ru_price_basis)
    U(f"acct.{a}.average_order", ru=net, unit=f"money per order before tax (ru: {ACCT[a][6]:,} as billed, VAT inside, / tax.vat_divisor)")
U("price.hour.company", unit="company-account hour today (A1 and A2), as the account pays it (ru: VAT inside; 1,619.05 before VAT); 10 % under list on parts and menu prices")
U("price.hour.company_history", unit="company-account hour at the same dates as price.hour.history, as the account pays it (ru: VAT inside from tax.ru_vat_from)")
