U("s7.bill", en={"inspection": 49.95, "front_pads_rotors": 493.0, "supplies": 12.15, "list_total": 555.1, "before_tax": 555.1, "tax": 51.35, "with_tax": 606.45, "declined_rear_shocks": 339.28, "declined_with_supplies": 347.38, "declined_before_tax": 347.38, "declined_with_tax": 379.51},
  ru={"inspection": 700, "front_pads_rotors": 12520, "supplies": 102.6, "list_total": 13322.6, "before_tax": 12688.19, "tax": 634.41, "with_tax": 13322.6, "declined_rear_shocks": 11720, "declined_with_supplies": 11811.2, "declined_before_tax": 11248.76, "declined_with_tax": 11811.2},
  unit="money, standard parts, class car, today's list, at main. list_total is the three lines added. en: tax is added (tax.rate.main). ru: the lines hold VAT, so with_tax equals list_total and before_tax is list_total / 1.05", check="recomputed from catalogue.json and tax.rate.main, tax.vat_divisor")
