NF = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "new_facts.json"), encoding="utf-8"))
for kind, folder, stores in (("call", "calls", "the call log and transcripts; the shop-system database (customers, cars, appointments, orders, as erp/generator-spec.md section 5 places them)"), ("conv", "conversations", "Chatwoot; the shop-system database; the picture and file pools")):
    for n in sorted({x["number"] for cfg in ("en", "ru") for x in NF[f"{kind}.{cfg}"]}):
        en = next((x for x in NF[f"{kind}.en"] if x["number"] == n and x["facts"]), None)
        ru = next((x for x in NF[f"{kind}.ru"] if x["number"] == n and x["facts"]), None)
        if en or ru:
            R(f"nf.{kind}.{n}", en=en["facts"] if en else None, ru=ru["facts"] if ru else None, unit="new facts of story " + ("call" if kind == "call" else "conversation") + f" {n}: " + " / ".join(x["file"] for x in (en, ru) if x), cls=X,
              reasoning="stated by the file itself (its new_facts), accepted in fix pass A as checks/new_facts.json froze them; invented people are in named_customers.json, facts about A1 to A6 in accounts.json", check="carried by: " + stores + ". checks/check_ledger.py compares the files' new_facts with the snapshot")


# A row the build measures: its key heads a band statement of erp/checks.sql. The value typed here is the design
# target the generator aims at; the value an eval expects is the build's, in manifest.<cfg>.json.
with open(os.path.join(os.path.dirname(OUT), "erp", "checks.sql"), encoding="utf-8") as f:
    BANDS = set(re.findall(r"^-- (\S+) \| band \|", f.read(), re.M))
for row in ROWS:
    if row["key"] in BANDS:
        row["outcome"] = True

meta = {
 "seed_version": "v1", "file": "ledger.json",
 "what": "the parameter ledger of demo seed v1 in machine form: the single place every number of the seed comes from. Built by checks/build_ledger.py; proved by checks/check_ledger.py.",
 "configurations": ["en", "ru"],
 "row": {"key": "stable key", "outcome": "true where the build measures the value: this file holds the design target, manifest.<cfg>.json the value of the build", "value | en, ru": "one value, or one per configuration", "unit": "what the value counts", "class": "measured (source and date) | measured-unverified | derived (formula) | designed (reasoning, range where one exists)", "mark": "fixed (a planted instance, the same in both sizes) | scales (grows with density) | rate (tolerance, min_count, n)", "tolerance": "absolute, in the row's unit unless tolerance_unit says otherwise", "n": "expected count of cases at full size the rate is read on, as a formula; None with 'open' where the count waits for another design part", "stories": "cards that use the row", "check": "how the seeded data is tested against the row", "decision": "accept | adjust | reject | open, on rows another file proposed", "open": "what is still to be designed"},
 "formula_language": "a Python expression; [key] stands for the row's value in the configuration being evaluated. Functions: sum, min, max, len, round, abs; mech_fte(site), shift_weight(site), sheet(prefix), worst_check(prefix), sum_rows(suffix), s6_counts(), s7_bill(), s12_brake(), cat_s8(field), cat_rec_hours(), cat_pad_share(), mixv(path) read the people rows, catalogue.json and mix.json as check_ledger.py defines them.",
 "notation": {"T": "time.t_rule", "G": "go-live: T - 175 days", "P": "the last price rise: the first Monday on or after T - 150 days", "W0, W-k, W+k": "the ISO week of T, k weeks before, k weeks after", "W90": "(T - 90 days, T]", "P1..P6": "30-day score periods from G"},
 "percentages": "written as per cent numbers (13.57 means 13.57 %)",
}
os.makedirs(os.path.dirname(OUT), exist_ok=True)
with open(OUT, "w", encoding="utf-8") as f:
    json.dump({"_meta": meta, "rows": ROWS}, f, ensure_ascii=False, indent=1)
